body:
Hola a todos,

No puedo hacer que esto funcione... Creo que estoy confundiendo algún concepto básico o tengo un gran bloqueo mental. ¿Alguien sabe cuál es el problema para ejecutar esta función?

Gracias de antemano...

--====================================
DROP TABLE test;
CREATE TABLE test
(
  clave numeric(7,0) not ,
  PRIMARY KEY (clave)
) WITHOUT OIDS;
--====================================
DROP FUNCTION f_test(numeric(7,0), numeric(7,0));
CREATE OR REPLACE FUNCTION f_test(numeric(7,0), numeric(7,0)) RETURNS timestamp AS '
  DECLARE
    p_datod ALIAS FOR $1;
    p_datoh ALIAS FOR $2;
    --
    tdesde timestamp;
    thasta timestamp;
  BEGIN
    tdesde := now();
    --
    FOR X IN p_datod..p_datoh LOOP
      INSERT INTO test VALUES (x);    
    END LOOP;
    --
    thasta := now() - tdesde;
    RETURN thasta;
  COMMIT;
  END;
' LANGUAGE 'plpgsql';
--====================================
select f_test(1,9);

---------------------------(fin de la transmisión)---------------------------
TIP 1: los comandos para suscribirse y cancelar la suscripción deben enviarse a majordomo@postgresql.org

